const rawStdout = $input.all()[0].json.stdout ? $input.all()[0].json.stdout.trim() : "";

try {
  const rawData = JSON.parse(rawStdout);
  const targetIp = $('Webhook').first().json.body.target || "Unknown Target";
  const toolName = $('Webhook').first().json.body.toolName || "unknown-tool"; 

  const formattedFindings = [];

  // 1. ดึงข้อมูลจาก Vulnerabilities
  const vulnerabilities = rawData.vulnerabilities || rawData.findings || [];
  if (Array.isArray(vulnerabilities) && vulnerabilities.length > 0) {
    vulnerabilities.forEach(vuln => {
      formattedFindings.push({
        title: vuln.title || vuln.name || "Unknown Vulnerability",
        severity: vuln.severity ? vuln.severity.toUpperCase() : "INFO",
        description: vuln.description || "No description provided.",
        remediation: vuln.remediation || vuln.solution || "Review findings and apply patches.",
        target: targetIp,
        cvss: vuln.cvss || vuln.cvss_score || null, // ✨ ดึงคะแนน CVSS มาใส่
        status: "OPEN",
        tool: toolName
      });
    });
  }

  // 2. ⭐️ ดึงข้อมูลจาก CVEs Identified มารวมด้วย (เพื่อไม่ให้ CVE หาย)
  const cves = rawData.cves_identified || [];
  if (Array.isArray(cves) && cves.length > 0) {
    cves.forEach(cve => {
      formattedFindings.push({
        title: cve.cve_id || "Unknown CVE", // ใช้รหัส CVE เป็นชื่อ
        severity: cve.risk_level ? cve.risk_level.toUpperCase() : "INFO", // แมประดับความเสี่ยง
        description: cve.description || "No description provided.",
        remediation: "Update to the latest secure version to mitigate this CVE.",
        target: targetIp,
        cvss: cve.cvss_score || cve.cvss || null, // ✨ ดึงคะแนน CVSS มาใส่
        status: "OPEN",
        tool: toolName
      });
    });
  }

  // 3. กรณีที่ Findings ว่างเปล่า แต่ AI มีการเขียนรายงานไว้ใน ai_decisions
  if (formattedFindings.length === 0 && rawData.ai_decisions && Array.isArray(rawData.ai_decisions) && rawData.ai_decisions.length > 0) {
    let combinedAiReport = "";

    rawData.ai_decisions.forEach(decision => {
      if (decision.decision) {
        combinedAiReport += decision.decision + "\n\n";
      }
    });

    formattedFindings.push({
      title: "Guardian AI Security Assessment Report",
      severity: "HIGH",
      description: "AI Generated Report:\n" + combinedAiReport.substring(0, 3000),
      remediation: "Please review the detailed AI text in the description for specific remediation steps.",
      target: targetIp,
      cvss: null,
      status: "OPEN",
      tool: toolName
    });
  }

  // 4. คืนค่าออกไปให้ Next.js
  return { findings: formattedFindings };

} catch (error) {
  return {
    findings: [{
      title: "Data Parsing Error",
      severity: "INFO",
      description: "Failed to parse JSON output. Error: " + error.message,
      remediation: "Check n8n Code node and raw tool output.",
      target: $('Webhook').first().json.body.target || "N/A",
      cvss: null,
      status: "IGNORED",
      tool: $('Webhook').first().json.body.toolName || "unknown-tool"
    }]
  };
}
